# the MCP session id and a fabricated cache path.
$bootstrapPayload = ''
try { $bootstrapPayload = Read-HookInput } catch { $bootstrapPayload = '' }
$providerSessionId = Get-HookPayloadValue -Payload $bootstrapPayload -Name 'session_id'

