16	function Get-McpCacheAgentKey {
17	    [CmdletBinding()]
18	    param()
19	
20	    # FR-MCP-SESSIONLIFE-002: inherited Grok variables must not move a Codex
21	    # plugin into the Grok cache namespace.
22	    $inheritedAgent = @($env:PLUGIN_AGENT_NAME, $env:MCP_AGENT_NAME) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
23	    if ($env:MCP_PLUGIN_HOST -match '^(?i:codex)$' -and $inheritedAgent -match '(?i)grok') {
24	        return 'codex'
25	    }
26	
27	    $agent = @(
28	        $env:MCP_AGENT_NAME,
29	        $env:PLUGIN_AGENT_NAME,
30	        $env:PLUGIN_AGENT_DEFAULT,
31	        $env:MCP_PLUGIN_HOST
32	    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
33	
34	    if (-not $agent) { return 'default' }
35	
36	    switch ($agent.Trim().ToLowerInvariant()) {
37	        'claude' { return 'claude' }
38	        'claudecode' { return 'claude' }
39	        'claude-code' { return 'claude' }
40	        'claudecowork' { return 'cowork' }
41	        'claude-cowork' { return 'cowork' }
42	        'codex' { return 'codex' }
43	        'copilot' { return 'copilot' }
44	        'grok' { return 'grok' }
