230	function Get-McpFailsafeAgentSegment {
231	    <#
232	    .SYNOPSIS
233	        Agent path segment matching FilesystemSessionLogPersistenceStrategy.SanitizePathSegment.
234	    #>
235	    [CmdletBinding()]
236	    param()
237	
238	    $inheritedAgent = @($env:PLUGIN_AGENT_NAME, $env:MCP_AGENT_NAME) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
239	    if ($env:MCP_PLUGIN_HOST -match '^(?i:codex)$' -and $inheritedAgent -match 'grok') {
240	        $agent = 'Codex'
241	    } else {
242	        $agent = @(
243	            $env:PLUGIN_AGENT_NAME,
244	            $env:MCP_AGENT_NAME,
245	            $env:PLUGIN_AGENT_DEFAULT,
246	            $env:MCP_PLUGIN_HOST
247	        ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
248	    }
249	
250	    if (-not $agent) {
251	        return (Get-McpCacheAgentKey)
252	    }
253	
254	    $builder = New-Object System.Text.StringBuilder
255	    foreach ($character in $agent.ToCharArray()) {
256	        if ([char]::IsLetterOrDigit($character) -or $character -eq '-' -or $character -eq '_' -or $character -eq '.') {
257	            [void]$builder.Append($character)
258	        } else {
259	            [void]$builder.Append('_')
260	        }
261	    }
262	
263	    $result = $builder.ToString().Trim('.')
264	    if ([string]::IsNullOrWhiteSpace($result)) { return 'unknown' }
265	    return $result
266	}
