282	function Resolve-McpFailsafeWorkspacePath {
283	    <#
284	    .SYNOPSIS
285	        Resolves the workspace root used for the V4 failsafe tree.
286	    #>
287	    [CmdletBinding()]
288	    param([string]$StartPath)
289	
290	    if (-not [string]::IsNullOrWhiteSpace($StartPath) -and (Test-Path -LiteralPath $StartPath -PathType Container)) {
291	        return [System.IO.Path]::GetFullPath($StartPath)
292	    }
293	
294	    $configured = Get-McpWorkspaceFromEnvironment
295	    if ($configured) { return $configured }
296	
297	    if (Get-Command Find-MarkerFile -ErrorAction SilentlyContinue) {
298	        $startCandidates = if (-not [string]::IsNullOrWhiteSpace($StartPath)) { @($StartPath) } else {
299	            @(
300	                $env:MCP_WORKSPACE_START_DIR,
301	                $env:MCP_WORKSPACE_PATH,
302	                $env:MCPSERVER_WORKSPACE_PATH,
