305	        }
306	        foreach ($startDir in $startCandidates) {
307	            try {
308	                $markerFile = Find-MarkerFile -StartDir $startDir
309	                if ($markerFile) {
310	                    return [System.IO.Path]::GetFullPath((Split-Path -Parent $markerFile))
311	                }
312	            } catch {
313	            }
314	        }
315	    }
