#Requires -Version 7.0
# Round3 retry review tool A04: read-only. Locate every plugin session cache (including hidden and ignored
# folders) and print the live history record of one ClaudeCode session so the hook-opened turn can be bound.
[CmdletBinding()]
param(
    [string]$SessionId = 'ClaudeCode-20261029T043632Z-plugin-session'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = '[HOME]/github/mcpserver-claude-code-plugin'
$ws = '[HOME]/github/WordGame/.mcpServer/wordpairs'
$wrapper = Join-Path $plugin 'lib/Invoke-McpPlugin.ps1'
Set-Location -LiteralPath $ws
Import-Module powershell-yaml -ErrorAction Stop
Write-Output ("LOCATE-TIME: {0}" -f (Get-Date -Format s))
$roots = @((Join-Path $ws '.mcpServer'), (Join-Path $plugin 'cache'), '[HOME]/github/WordGame/.mcpServer/mcpserver-claude-code-plugin')
foreach ($root in $roots) {
    if (-not (Test-Path -LiteralPath $root)) { Write-Output ("ROOT-MISSING {0}" -f $root); continue }
    foreach ($f in @(Get-ChildItem -LiteralPath $root -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -in @('session-state.yaml', 'current-turn.yaml', 'session-verb-outcome.yaml') })) {
        $text = Get-Content -LiteralPath $f.FullName -Raw
        $sid = [regex]::Match($text, '(?m)^sessionId:\s*(.+)$').Groups[1].Value
        $rid = [regex]::Match($text, '(?m)^(turnRequestId|requestId):\s*(.+)$').Groups[2].Value
        $st = [regex]::Match($text, '(?m)^status:\s*(.+)$').Groups[1].Value
        Write-Output ("CACHE {0} {1} sessionId={2} requestId={3} status={4}" -f $f.LastWriteTime.ToString('s'), $f.FullName, $sid, $rid, $st)
    }
}
$raw = ''
try {
    $raw = (& $wrapper -Command Invoke -Method 'workflow.sessionlog.queryHistory' -ParamsObject ([ordered]@{ agent = 'ClaudeCode'; limit = 6; offset = 0 }) -WorkspacePath $ws -PluginRoot $plugin -TimeoutSeconds 180 2>&1 | Out-String)
} catch { $raw = 'WRAPPER-ERROR: ' + $_.Exception.Message }
$doc = $null
try { $doc = ConvertFrom-Yaml -Yaml $raw -Ordered } catch { $doc = $null }
if ($null -eq $doc) { Write-Output ('HISTORY-PARSE-FAILED ' + $raw.Substring(0, [Math]::Min(1200, $raw.Length))); return }
$json = $doc | ConvertTo-Json -Depth 40 -Compress
$json = [regex]::Replace($json, '(?i)(api[_-]?key["'':\s=]+)[A-Za-z0-9_\-]{20,}', '$1<redacted>')
$idx = $json.IndexOf($SessionId)
Write-Output ("HISTORY length={0} sessionIndex={1}" -f $json.Length, $idx)
if ($idx -ge 0) {
    $start = [Math]::Max(0, $idx - 1500)
    Write-Output $json.Substring($start, [Math]::Min(4500, $json.Length - $start))
}

