#Requires -Version 7.0
# Round3 retry review tool A07: read-only evidence verification. Hashes every report named by the evidence index,
# parses native JUnit and TRX case by case, compares names/outcomes, prints JUnit execution timestamps, and
# re-verifies the frozen source manifest against independent Git inventories and current bytes.
[CmdletBinding()]
param(
    [string]$Index = '[HOME]/github/WordGame/.mcpServer/wordpairs/docs/evidence/hosting/guest-admin-recovery/round3-frozen-evidence-1c22727/evidence-index.json'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ws = '[HOME]/github/WordGame/.mcpServer/wordpairs'
$head = '1c2272714fb02091e390f751510341e6824e3d22'
Write-Output ("EVIDENCE-TIME: {0}" -f (Get-Date -Format s))
$idx = Get-Content -LiteralPath $Index -Raw | ConvertFrom-Json

function Get-JUnitCase {
    param([string]$Path)
    [xml]$x = Get-Content -LiteralPath $Path -Raw
    $suites = @($x.SelectNodes('//testsuite'))
    $cases = foreach ($tc in @($x.SelectNodes('//testcase'))) {
        $outcome = 'Passed'
        if ($tc.SelectSingleNode('failure') -or $tc.SelectSingleNode('error')) { $outcome = 'Failed' }
        elseif ($tc.SelectSingleNode('skipped')) { $outcome = 'Skipped' }
        [pscustomobject]@{ Name = ('{0} :: {1}' -f $tc.GetAttribute('classname'), $tc.GetAttribute('name')); Outcome = $outcome; Time = $tc.GetAttribute('time') }
    }
    $stamps = @($suites | ForEach-Object { $_.GetAttribute('timestamp') } | Where-Object { $_ } | Sort-Object)
    $root = $x.DocumentElement
    return [pscustomobject]@{ Cases = @($cases); FirstStamp = ($stamps | Select-Object -First 1); LastStamp = ($stamps | Select-Object -Last 1); RootTimestamp = $root.GetAttribute('timestamp'); RootTime = $root.GetAttribute('time'); Suites = $suites.Count }
}

function Get-TrxCase {
    param([string]$Path)
    [xml]$x = Get-Content -LiteralPath $Path -Raw
    $ns = New-Object System.Xml.XmlNamespaceManager($x.NameTable)
    $ns.AddNamespace('t', $x.DocumentElement.NamespaceURI)
    $results = @($x.SelectNodes('//t:UnitTestResult', $ns))
    $times = $x.SelectSingleNode('//t:Times', $ns)
    $counters = $x.SelectSingleNode('//t:Counters', $ns)
    $cases = foreach ($r in $results) { [pscustomobject]@{ Name = $r.GetAttribute('testName'); Outcome = $r.GetAttribute('outcome'); Start = $r.GetAttribute('startTime') } }
    $countText = if ($counters) { ($counters.Attributes | ForEach-Object { '{0}={1}' -f $_.Name, $_.Value }) -join ' ' } else { 'none' }
    $timeText = if ($times) { ($times.Attributes | ForEach-Object { '{0}={1}' -f $_.Name, $_.Value }) -join ' ' } else { 'none' }
    return [pscustomobject]@{ Cases = @($cases); Counters = $countText; Times = $timeText }
}

foreach ($r in $idx.reports) {
    Write-Output ("== {0}" -f $r.name)
    $jh = (Get-FileHash -LiteralPath $r.junit -Algorithm SHA256).Hash
    $th = (Get-FileHash -LiteralPath $r.trx -Algorithm SHA256).Hash
    Write-Output ("  junitHashMatch={0} trxHashMatch={1} junitMtime={2} trxMtime={3}" -f ($jh -eq $r.junitSha256), ($th -eq $r.trxSha256), (Get-Item -LiteralPath $r.junit).LastWriteTime.ToString('s'), (Get-Item -LiteralPath $r.trx).LastWriteTime.ToString('s'))
    $j = Get-JUnitCase -Path $r.junit
    $t = Get-TrxCase -Path $r.trx
    $jg = $j.Cases | Group-Object Outcome | ForEach-Object { '{0}={1}' -f $_.Name, $_.Count }
    $tg = $t.Cases | Group-Object Outcome | ForEach-Object { '{0}={1}' -f $_.Name, $_.Count }
    Write-Output ("  junit cases={0} [{1}] suites={2} rootTimestamp={3} firstSuite={4} lastSuite={5} rootTime={6}" -f $j.Cases.Count, ($jg -join ','), $j.Suites, $j.RootTimestamp, $j.FirstStamp, $j.LastStamp, $j.RootTime)
    Write-Output ("  trx cases={0} [{1}] counters=[{2}] times=[{3}]" -f $t.Cases.Count, ($tg -join ','), $t.Counters, $t.Times)
    $jNames = @($j.Cases | ForEach-Object { $_.Name })
    $tNames = @($t.Cases | ForEach-Object { $_.Name })
    $dupJ = @($jNames | Group-Object | Where-Object Count -gt 1)
    Write-Output ("  junitDuplicateNames={0} indexCases={1} indexFailed={2} indexSkipped={3}" -f $dupJ.Count, $r.cases, $r.failed, $r.skipped)
    $onlyJ = @($jNames | Where-Object { $_ -notin $tNames })
    $onlyT = @($tNames | Where-Object { $_ -notin $jNames })
    Write-Output ("  namesOnlyInJUnit={0} namesOnlyInTrx={1}" -f $onlyJ.Count, $onlyT.Count)
    foreach ($n in ($onlyJ | Select-Object -First 3)) { Write-Output ("    J-only: {0}" -f $n) }
    foreach ($n in ($onlyT | Select-Object -First 3)) { Write-Output ("    T-only: {0}" -f $n) }
    foreach ($c in @($j.Cases | Where-Object Outcome -ne 'Passed')) { Write-Output ("    NON-PASS junit: {0} {1}" -f $c.Outcome, $c.Name) }
}

Write-Output '== source manifest'
$manifestPath = $idx.sourceManifest
Write-Output ("  manifestHashMatch={0}" -f ((Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash -eq $idx.sourceManifestSha256))
$m = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
$pattern = '^(src|tests|scripts|public)/|^(package(-lock)?\.json|tsconfig\.json|next-env\.d\.ts|next\.config\.ts|biome\.json|vitest[^/]*\.config\.ts|playwright[^/]*\.config\.ts)$'
$treePaths = @(& git -C $ws ls-tree -r --name-only $head | Where-Object { $_ -match $pattern } | Sort-Object -Unique)
$manifestPaths = @($m.sourceHashes | ForEach-Object { $_.path } | Sort-Object -Unique)
$missing = @($treePaths | Where-Object { $_ -notin $manifestPaths })
$extra = @($manifestPaths | Where-Object { $_ -notin $treePaths })
Write-Output ("  headTreeScopedPaths={0} manifestPaths={1} missingFromManifest={2} extraInManifest={3}" -f $treePaths.Count, $manifestPaths.Count, $missing.Count, $extra.Count)
foreach ($p in $missing) { Write-Output ("    MISSING {0}" -f $p) }
foreach ($p in $extra) { Write-Output ("    EXTRA {0}" -f $p) }
$mismatch = 0
foreach ($e in $m.sourceHashes) {
    $abs = Join-Path $ws $e.path
    if (-not (Test-Path -LiteralPath $abs -PathType Leaf)) { Write-Output ("    ABSENT-NOW {0}" -f $e.path); $mismatch++; continue }
    $h = (Get-FileHash -LiteralPath $abs -Algorithm SHA256).Hash
    if ($h -ne $e.sha256) { Write-Output ("    BYTES-CHANGED {0}" -f $e.path); $mismatch++ }
}
Write-Output ("  currentByteMismatches={0}" -f $mismatch)
$rootTracked = @(& git -C $ws ls-tree --name-only $head)
Write-Output ("  headRootEntries: {0}" -f ($rootTracked -join ', '))
$outsideScope = @(& git -C $ws diff --name-only "8e2f62417e0fe46cefd884e8a61024b12860a2cf..$head" | Where-Object { $_ -notmatch $pattern -and $_ -notmatch '^docs/' })
Write-Output ("  changedOutsideManifestScopeAndDocs: {0}" -f ($outsideScope -join ', '))

