# Round3 retry review tool A08: read-only. Print last-write times and SHA-256 for a comma-separated list of
# workspace-relative paths (files or directories, directories listed one level, sorted by time).
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$PathList
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ws = '[HOME]/github/WordGame/.mcpServer/wordpairs'
Write-Output ("MTIME-TIME: {0}" -f (Get-Date -Format s))
foreach ($rel in @($PathList -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) {
    $abs = Join-Path $ws $rel
    if (-not (Test-Path -LiteralPath $abs)) { Write-Output ("ABSENT {0}" -f $rel); continue }
    $item = Get-Item -LiteralPath $abs -Force
    if ($item.PSIsContainer) {
        foreach ($f in (Get-ChildItem -LiteralPath $abs -File -Force | Sort-Object LastWriteTime)) {
            Write-Output ("{0} {1} {2}" -f $f.LastWriteTime.ToString('s'), (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.Substring(0, 16), $f.FullName.Substring($ws.Length + 1))
        }
    } else {
        Write-Output ("{0} {1} {2}" -f $item.LastWriteTime.ToString('s'), (Get-FileHash -LiteralPath $abs -Algorithm SHA256).Hash, $rel)
    }
}

