1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	
5	interface InstallPrompt extends Event {
6	  prompt(): Promise<void>;
7	  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
8	}
9	
10	export function PwaSupport() {
11	  const [installed, setInstalled] = useState(true);
12	  const [secure, setSecure] = useState(true);
13	  const [installPrompt, setInstallPrompt] = useState<InstallPrompt | null>(
14	    null,
15	  );
16	  const [message, setMessage] = useState("");
17	  const prompting = useRef(false);
18	
19	  useEffect(() => {
20	    let active = true;
21	    const media = window.matchMedia("(display-mode: standalone)");
22	    const isInstalled = () =>
23	      media.matches ||
24	      ("standalone" in navigator && navigator.standalone === true);
25	    const modeChanged = () => setInstalled(isInstalled());
26	    const ready = (event: Event) => {
27	      event.preventDefault();
28	      setInstallPrompt(event as InstallPrompt);
29	    };
30	    const appInstalled = () => {
31	      setInstalled(true);
32	      setInstallPrompt(null);
33	    };
34	    modeChanged();
35	    setSecure(window.isSecureContext);
36	    window.addEventListener("beforeinstallprompt", ready);
37	    window.addEventListener("appinstalled", appInstalled);
38	    media.addEventListener("change", modeChanged);
39	    if (window.isSecureContext && "serviceWorker" in navigator) {
40	      navigator.serviceWorker
41	        .register("/admin-sw.js", { scope: "/admin", updateViaCache: "none" })
42	        .catch(() => {
43	          if (active)
44	            setMessage(
45	              "Installation support could not start. Reload to retry, or use your browser’s install menu.",
46	            );
47	        });
48	    }
49	    return () => {
50	      active = false;
51	      window.removeEventListener("beforeinstallprompt", ready);
52	      window.removeEventListener("appinstalled", appInstalled);
53	      media.removeEventListener("change", modeChanged);
54	    };
55	  }, []);
56	
57	  async function install() {
58	    if (!installPrompt || prompting.current) return;
59	    const event = installPrompt;
60	    prompting.current = true;
61	    setInstallPrompt(null);
62	    try {
63	      await event.prompt();
64	      const choice = await event.userChoice;
65	      setMessage(
66	        choice.outcome === "accepted"
67	          ? "Finish installing in your browser’s prompt."
68	          : "You can install later from your browser’s menu.",
69	      );
70	    } catch {
71	      setMessage("Use your browser’s install menu or the instructions below.");
72	    } finally {
73	      prompting.current = false;
74	    }
75	  }
76	
77	  if (installed) return null;
78	  return (
79	    <aside
80	      className="site-shell pwa-install"
81	      aria-label="Install Wordpairs Admin"
82	    >
83	      {secure && installPrompt && (
84	        <button type="button" onClick={install}>
85	          Install Wordpairs Admin
86	        </button>
87	      )}
88	      <details>
89	        <summary>Get Wordpairs Admin on your phone</summary>
90	        <p>
91	          <strong>iPhone:</strong> Open this site in Safari, tap Share, then Add
92	          to Home Screen. Keep Open as Web App enabled if offered.
93	        </p>
94	        <p>
95	          <strong>Android:</strong> Open your browser’s menu and choose Install
96	          app or Add to Home screen. The wording depends on your browser.
97	        </p>
98	        <p>
99	          Opens administration from your home screen. A connection and GitHub
100	          sign-in are required.
101	        </p>
102	      </details>
103	      {!secure && (
104	        <p>
105	          Installation requires a secure HTTPS address. Localhost is supported
106	          for development.
107	        </p>
108	      )}
109	      {message && <p role="status">{message}</p>}
110	    </aside>
111	  );
112	}
113	/** Retire only the former public-game worker/cache; leave admin and other apps intact. */
114	export function LegacyPwaCleanup() {
115	  useEffect(() => {
116	    if ("serviceWorker" in navigator) {
117	      void navigator.serviceWorker
118	        .getRegistrations()
119	        .then(async (registrations) => {
120	          for (const registration of registrations) {
121	            const worker =
122	              registration.active ??
123	              registration.waiting ??
124	              registration.installing;
125	            if (
126	              new URL(registration.scope).pathname === "/" &&
127	              worker &&
128	              new URL(worker.scriptURL).pathname === "/sw.js"
129	            )
130	              await registration.unregister();
131	          }
132	        })
133	        .catch(() => {});
134	    }
135	    if (typeof caches !== "undefined") {
136	      void caches
137	        .keys()
138	        .then((keys) =>
139	          Promise.all(
140	            keys
141	              .filter((key) => key.startsWith("wordpairs-pwa-"))
142	              .map((key) => caches.delete(key)),
143	          ),
144	        )
145	        .catch(() => {});
146	    }
147	  }, []);
148	  return null;
149	}
