1	"use client";
2	import Link from "next/link";
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { type OwnProfile, PROFILE_ICONS } from "../application/identity";
5	import type { Permission } from "../domain/access";
6	import { guestCredential } from "./guest-credential";
7	import { usePrivateDraftState } from "./private-draft";
8	import { bindPrivateIdentity } from "./private-state";
9	import { PwaSupport } from "./pwa-support";
10	import { usePrivateIntent } from "./use-private-intent";
11	
12	const ICONS: Record<string, string> = {
13	  owl: "🦉",
14	  fox: "🦊",
15	  frog: "🐸",
16	  cat: "🐈",
17	  whale: "🐳",
18	  bee: "🐝",
19	};
20	export function ProfileIcon({ icon }: { icon: string }) {
21	  return (
22	    <span role="img" aria-label={icon}>
23	      {ICONS[icon] ?? "●"}
24	    </span>
25	  );
26	}
27	export function IdentityPanel({
28	  oidcEnabled,
29	  onProfile,
30	  administration = false,
31	}: {
32	  oidcEnabled: boolean;
33	  onProfile?: (profile: OwnProfile | null) => void;
34	  administration?: boolean;
35	}) {
36	  const [profile, setProfile] = useState<OwnProfile | null>(null);
37	  const [loading, setLoading] = useState(true);
38	  const [error, setError] = useState("");
39	  const [initialized, setInitialized] = useState(false);
40	  const [signInFailed, setSignInFailed] = useState(false);
41	  const [permissions, setPermissions] = useState<Permission[]>([]);
42	  const generation = useRef(0);
43	  const running = useRef(false);
44	  const endpoint = administration ? "/api/admin/session" : "/api/session";
45	  useEffect(() => {
46	    setSignInFailed(
47	      administration &&
48	        new URL(window.location.href).searchParams.get("auth") === "failed",
49	    );
50	  }, [administration]);
51	  const accept = useCallback(
52	    (
53	      current: OwnProfile | null,
54	      sessionGeneration?: string,
55	      grants: Permission[] = [],
56	    ) => {
57	      bindPrivateIdentity(current?.id ?? null, sessionGeneration);
58	      setProfile(current);
59	      setPermissions(administration && current ? grants : []);
60	      onProfile?.(current);
61	    },
62	    [onProfile, administration],
63	  );
64	  const load = useCallback(
65	    async (quiet = false) => {
66	      if (quiet && running.current) return;
67	      const sequence = ++generation.current;
68	      if (!quiet) setLoading(true);
69	      setError("");
70	      try {
71	        const response = await fetch(endpoint, {
72	          cache: "no-store",
73	          signal: AbortSignal.timeout(10000),
74	        });
75	        if (!response.ok && response.status !== 401)
76	          throw new Error("Unavailable");
77	        const result = response.ok ? await response.json() : null;
78	        if (!response.ok) await response.text();
79	        if (sequence === generation.current)
80	          accept(
81	            result?.profile ?? null,
82	            result?.sessionGeneration ?? undefined,
83	            Array.isArray(result?.permissions) ? result.permissions : [],
84	          );
85	      } catch {
86	        if (sequence === generation.current) {
87	          setPermissions([]);
88	          setError("Your profile is unavailable. Try again.");
89	        }
90	      } finally {
91	        if (sequence === generation.current) {
92	          setLoading(false);
93	          setInitialized(true);
94	        }
95	      }
96	    },
97	    [accept, endpoint],
98	  );
99	  useEffect(() => {
100	    void load();
101	    const timer = setInterval(() => void load(true), 15000);
102	    const focus = () => {
103	      if (running.current) return;
104	      setPermissions([]);
105	      void load();
106	    };
107	    window.addEventListener("focus", focus);
108	    return () => {
109	      clearInterval(timer);
110	      window.removeEventListener("focus", focus);
111	      generation.current++;
112	    };
113	  }, [load]);
114	  const session = async (method: "POST" | "DELETE") => {
115	    if (running.current) return;
116	    running.current = true;
117	    const sequence = ++generation.current;
118	    setLoading(true);
119	    setPermissions([]);
120	    setError("");
121	    try {
122	      const body =
123	        method === "POST"
124	          ? JSON.stringify({ guestCredential: await guestCredential() })
125	          : undefined;
126	      const response = await fetch(endpoint, {
127	        method,
128	        signal: AbortSignal.timeout(10000),
129	        headers: { "Content-Type": "application/json" },
130	        body,
131	      });
132	      if (!response.ok) throw new Error("Unavailable");
133	      const result = method === "POST" ? await response.json() : null;
134	      if (sequence === generation.current) {
135	        accept(result?.profile ?? null, result?.sessionGeneration ?? undefined);
136	        if (method === "POST") await load();
137	      }
138	    } catch {
139	      if (sequence === generation.current)
140	        setError(
141	          method === "POST"
142	            ? "Could not continue as guest. Check your connection and allow browser site data, then try again."
143	            : "Could not sign out. Try again.",
144	        );
145	    } finally {
146	      running.current = false;
147	      if (sequence === generation.current) setLoading(false);
148	    }
149	  };
150	  return (
151	    <section
152	      className="panel identity-panel"
153	      aria-labelledby="profile-heading"
154	      aria-busy={loading}
155	    >
156	      <p className="eyebrow">Make yourself at home</p>
157	      <h1 id="profile-heading">
158	        {administration
159	          ? "Administration"
160	          : profile
161	            ? "Your player profile"
162	            : "Ready for some wordplay?"}
163	      </h1>
164	      {error && (
165	        <p role="alert">
166	          {error}{" "}
167	          <button type="button" disabled={loading} onClick={() => void load()}>
168	            Retry profile
169	          </button>
170	        </p>
171	      )}
172	      {signInFailed && !profile && (
173	        <p role="alert">
174	          GitHub sign-in was not accepted. Only sharpninja can administer
175	          Wordpairs. Try signing in again.
176	        </p>
177	      )}
178	      {loading && <p role="status">Loading your profile…</p>}
179	      {profile ? (
180	        <>
181	          <p className="profile-alias">
182	            <ProfileIcon icon={profile.icon} /> <strong>{profile.alias}</strong>
183	          </p>
184	          <p>
185	            {profile.kind === "guest"
186	              ? "Guest profile saved in this browser."
187	              : "Signed-in profile."}{" "}
188	            {profile.wins} lifetime wins · {profile.points} points
189	          </p>
190	          <details>
191	            <summary>Profile details</summary>
192	            <p className="admin-id">
193	              Profile ID: <code>{profile.id}</code>
194	            </p>
195	            {permissions.includes("moderate") && !administration && (
196	              <Link href="/admin">Administration</Link>
197	            )}
198	          </details>
199	          {administration && permissions.length > 0 && (
200	            <nav className="admin-nav" aria-label="Administration">
201	              {permissions.includes("moderate") && (
202	                <Link href="/admin">Moderation</Link>
203	              )}
204	              {permissions.includes("manage-content") && (
205	                <Link href="/admin/words">Word pairs and hints</Link>
206	              )}
207	            </nav>
208	          )}
209	          {administration && permissions.includes("moderate") && <PwaSupport />}
210	          {!administration && (
211	            <ProfilePreferences
212	              key={profile.id}
213	              profile={profile}
214	              loading={loading}
215	              refresh={load}
216	              denied={() => accept(null)}
217	            />
218	          )}
219	          <div className="hero-actions">
220	            <button
221	              type="button"
222	              disabled={loading}
223	              onClick={() => void session("DELETE")}
224	            >
225	              Sign out
226	            </button>
227	          </div>
228	          {profile.kind === "guest" && (
229	            <p className="panel-note">
230	              Clearing this browser’s site data resets your guest identity.
231	            </p>
232	          )}
233	        </>
234	      ) : (
235	        <>
236	          <p>
237	            {administration
238	              ? "Administration is restricted to the GitHub account sharpninja."
239	              : "Play as a guest in this browser. No account is needed."}
240	          </p>
241	          <div className="hero-actions">
242	            {!administration && (
243	              <button
244	                type="button"
245	                className="button"
246	                disabled={loading || !initialized}
247	                onClick={() => void session("POST")}
248	              >
249	                Continue as guest
250	              </button>
251	            )}
252	            {administration && <AdminSignIn enabled={oidcEnabled} />}
253	          </div>
254	        </>
255	      )}
256	    </section>
257	  );
258	}
259	function AdminSignIn({ enabled }: { enabled: boolean }) {
260	  return enabled ? (
261	    <a className="button secondary" href="/api/auth/github/login">
262	      Sign in with GitHub
263	    </a>
264	  ) : (
265	    <div>
266	      <button
267	        type="button"
268	        className="button secondary"
269	        disabled
270	        aria-describedby="github-unavailable"
271	      >
272	        Sign in with GitHub
273	      </button>
274	      <p id="github-unavailable" className="panel-note">
275	        GitHub administrator sign-in is being configured.
276	      </p>
277	    </div>
278	  );
279	}
280	function ProfilePreferences({
281	  profile,
282	  loading,
283	  refresh,
284	  denied,
285	}: {
286	  profile: OwnProfile;
287	  loading: boolean;
288	  refresh: () => Promise<void>;
289	  denied: () => void;
290	}) {
291	  const intent = usePrivateIntent(profile.id, refresh, denied, "profile");
292	  const [editing, setEditing, clearEditing] = usePrivateDraftState<{
293	    icon: string;
294	    publicLeaderboard: boolean;
295	    regenerateAlias: boolean;
296	  } | null>(profile.id, "profile-editor", null);
297	  const opener = useRef<HTMLButtonElement>(null);
298	  const dialog = useRef<HTMLDialogElement>(null);
299	  const editingOpen = editing !== null;
300	  useEffect(() => {
301	    const modal = dialog.current;
302	    if (editingOpen && modal && !modal.open) modal.showModal();
303	    return () => {
304	      if (modal?.open) modal.close();
305	    };
306	  }, [editingOpen]);
307	  const restoreFocus = useRef(false);
308	  useEffect(() => {
309	    if (!editing && !loading && !intent.locked && restoreFocus.current) {
310	      restoreFocus.current = false;
311	      opener.current?.focus();
312	    }
313	  }, [editing, loading, intent.locked]);
314	  const update = (input: Record<string, unknown>, draftKey?: string) =>
315	    intent.send(
316	      "/api/profile",
317	      {
318	        ...input,
319	        expectedVersion: profile.version,
320	      },
321	      draftKey,
322	      "PATCH",
323	    );
324	  return (
325	    <>
326	      {!editing && intent.error && <p role="alert">{intent.error}</p>}
327	      {!editing && intent.notice && <p role="status">{intent.notice}</p>}
328	      {!editing && intent.busy && <p role="status">Saving your profile…</p>}
329	      <fieldset disabled={loading || intent.locked || !!editing}>
330	        <legend>Choose your icon</legend>
331	        <div className="icon-picker">
332	          {PROFILE_ICONS.map((icon) => (
333	            <button
334	              key={icon}
335	              type="button"
336	              aria-label={`Choose ${icon}`}
337	              aria-pressed={profile.icon === icon}
338	              onClick={() => void update({ icon })}
339	            >
340	              <ProfileIcon icon={icon} />
341	            </button>
342	          ))}
343	        </div>
344	      </fieldset>
345	      <label className="checkbox-label">
346	        <input
347	          type="checkbox"
348	          checked={profile.publicLeaderboard}
349	          disabled={loading || intent.locked || !!editing}
350	          onChange={(event) =>
351	            void update({ publicLeaderboard: event.target.checked })
352	          }
353	        />{" "}
354	        Show my generated alias on the public leaderboard
355	      </label>
356	      <div className="hero-actions">
357	        <button
358	          type="button"
359	          disabled={loading || intent.locked || !!editing}
360	          onClick={() => void update({ regenerateAlias: true })}
361	        >
362	          Generate another alias
363	        </button>
364	        <button
365	          ref={opener}
366	          type="button"
367	          disabled={loading || intent.locked || !!editing}
368	          onClick={() =>
369	            setEditing({
370	              icon: profile.icon,
371	              publicLeaderboard: profile.publicLeaderboard,
372	              regenerateAlias: false,
373	            })
374	          }
375	        >
376	          Edit profile
377	        </button>
378	      </div>
379	      {editing && (
380	        <dialog
381	          ref={dialog}
382	          aria-labelledby="edit-profile-title"
383	          onCancel={(event) => {
384	            event.preventDefault();
385	            if (!intent.locked) {
386	              restoreFocus.current = true;
387	              clearEditing();
388	            }
389	          }}
390	        >
391	          <h2 id="edit-profile-title">Edit profile</h2>
392	          {intent.error && <p role="alert">{intent.error}</p>}
393	          {intent.busy && <p role="status">Saving your profile…</p>}
394	          <form
395	            onSubmit={(event) => {
396	              event.preventDefault();
397	              restoreFocus.current = true;
398	              void update(editing, "profile-editor");
399	            }}
400	          >
401	            <fieldset disabled={loading || intent.locked}>
402	              <legend>Edit profile preferences</legend>
403	              <p>
404	                Saved alias: {profile.alias}. A new alias is generated only when
405	                you save.
406	              </p>
407	              <label>
408	                Draft profile icon
409	                <select
410	                  value={editing.icon}
411	                  onChange={(event) =>
412	                    setEditing({ ...editing, icon: event.target.value })
413	                  }
414	                >
415	                  {PROFILE_ICONS.map((icon) => (
416	                    <option key={icon} value={icon}>
417	                      {icon}
418	                    </option>
419	                  ))}
420	                </select>
421	              </label>
422	              <label className="checkbox-label">
423	                <input
424	                  type="checkbox"
425	                  checked={editing.regenerateAlias}
426	                  onChange={(event) =>
427	                    setEditing({
428	                      ...editing,
429	                      regenerateAlias: event.target.checked,
430	                    })
431	                  }
432	                />
433	                Generate a new alias on Save
434	              </label>
435	              <label className="checkbox-label">
