250	    };
251	  }, [profile.id, room?.role, room?.status, refresh]);
252	  const command = async (
253	    action: "join" | "invite" | "ready" | "leave",
254	    mode?: "player" | "observer",
255	  ) => {
256	    if (!room || !profile || inFlight.current) return;
257	    inFlight.current = true;
258	    const epoch = commandEpoch.current;
259	    setBusy(true);
260	    setError("");
261	    if (action === "invite") setCopyMessage("");
262	    let provideCopy: ((url: string) => void) | undefined;
263	    let abortCopy: (() => void) | undefined;
264	    let copyResult: Promise<boolean> | undefined;
265	    if (
266	      action === "invite" &&
267	      navigator.clipboard?.write &&
268	      typeof ClipboardItem !== "undefined"
269	    ) {
270	      const content = new Promise<Blob>((resolve, reject) => {
271	        provideCopy = (url) => {
272	          resolve(new Blob([url], { type: "text/plain" }));
273	          provideCopy = undefined;
274	          abortCopy = undefined;
275	        };
276	        abortCopy = () => {
277	          reject(new Error("Invitation was not created"));
278	          provideCopy = undefined;
279	          abortCopy = undefined;
280	        };
281	      });
282	      // A denied clipboard request may stop observing the pending data promise.
283	      void content.catch(() => {});
284	      try {
285	        // Begin the clipboard operation during the click; its data arrives after
286	        // the server creates the inviter-bound link.
287	        copyResult = navigator.clipboard
288	          .write([new ClipboardItem({ "text/plain": content })])
289	          .then(
290	            () => true,
291	            () => false,
292	          );
293	      } catch {
294	        abortCopy?.();
295	      }
296	    }
297	    const input = pending.current ?? {
298	      action,
299	      expectedProfileId: profile.id,
300	      commandId: crypto.randomUUID(),
301	      expectedVersion: room.version,
302	      ...(mode ? { mode, inviterId: room.inviterId ?? selected } : {}),
303	      ...(action === "ready"
304	        ? { ready: !room.players.find((p) => p.id === profile.id)?.ready }
305	        : {}),
306	    };
307	    if (action !== "invite") pending.current = input;
308	    let explanation = "Room access is unavailable. Retry the same request.";
309	    try {
310	      const response = await fetch(
311	        ["ready", "leave"].includes(input.action as string)
312	          ? `/api/rooms/${encodeURIComponent(room.roomId)}/lobby`
313	          : endpoint,
314	        {
315	          method: "POST",
316	          signal: AbortSignal.timeout(10000),
317	          headers: { "Content-Type": "application/json" },
318	          body: JSON.stringify(input),
319	        },
320	      );
321	      if (epoch !== commandEpoch.current) {
322	        await response.text();
323	        return;
324	      }
325	      if ([401, 403, 404].includes(response.status)) {
326	        deny();
327	        await response.text();
328	        return;
329	      }
330	      const result = await response.json();
331	      if (epoch !== commandEpoch.current) return;
332	      if (response.ok || response.status < 500) {
333	        // A pre-command preview cannot decide membership or discovery recovery.
334	        // Retire it before clearing the canonical intent and read fresh state.
335	        sequence.current++;
336	        fetching.current = false;
337	        refreshAgain.current = false;
338	      }
339	      if (!response.ok) {
340	        if (response.status < 500) pending.current = null;
341	        if (
342	          fromDiscovery &&
343	          input.action === "join" &&
344	          input.mode === "player" &&
345	          response.status === 409
346	        ) {
347	          await refresh(true);
348	          return;
349	        }
350	        explanation =
351	          response.status === 409
352	            ? "The room or account changed. Refresh and try again."
353	            : "Your request was not confirmed. Retry the same request.";
354	        throw new Error("Unavailable");
355	      }
356	      pending.current = null;
357	      if (input.action === "leave") {
358	        window.location.assign("/play");
359	        return;
360	      }
361	      if (input.action === "invite") {
362	        if (typeof result.url !== "string" || !result.url) {
363	          throw new Error("Invalid invitation");
364	        }
365	        setLink(result.url);
366	        provideCopy?.(result.url);
367	        let copied = false;
368	        if (copyResult) {
369	          copied = await copyResult;
370	        } else {
371	          try {
372	            if (navigator.clipboard?.writeText) {
373	              await navigator.clipboard.writeText(result.url);
374	              copied = true;
375	            }
376	          } catch {
377	            // The visible link remains available for manual copying.
378	          }
379	        }
380	        if (epoch !== commandEpoch.current) return;
381	        setCopyMessage(
382	          copied
383	            ? "Invitation link copied."
384	            : "Could not copy automatically. Select the link to copy it.",
385	        );
386	      } else setActiveRef(result.roomId);
387	      await refresh();
388	    } catch {
389	      if (epoch === commandEpoch.current) setError(explanation);
390	    } finally {
391	      abortCopy?.();
392	      inFlight.current = false;
393	      if (epoch === commandEpoch.current) setBusy(false);
394	    }
395	  };
396	  const live = useRoomUpdates(
397	    profile?.id ?? null,
398	    room?.role ? room.roomId : null,
399	    refresh,
400	  );
401	  return (
402	    <>
403	      {profile && (
404	        <section
405	          className="panel room-panel"
406	          aria-labelledby="room-title"
407	          aria-busy={busy}
408	          data-room-version={room?.version}
409	        >
410	          <div className="panel-heading">
411	            <h1 id="room-title">
412	              {room?.role === "observer" ? "Observer seat" : "The room"}
413	            </h1>
414	            <button
415	              type="button"
416	              disabled={busy}
417	              onClick={() => void refresh()}
418	            >
419	              Refresh room
420	            </button>
421	          </div>
422	          {error && <p role="alert">{error}</p>}
423	          {room?.role && (
424	            <p role="status">
425	              {live
426	                ? "● Live updates connected"
427	                : "○ Live updates unavailable. Retrying; room refresh remains available."}
