  ) {
    const content = new Promise<Blob>((resolve, reject) => {
      provideCopy = (url) => {
        resolve(new Blob([url], { type: "text/plain" }));
        provideCopy = undefined;
        abortCopy = undefined;
      };
      abortCopy = () => {
        reject(new Error("Invitation was not created"));
        provideCopy = undefined;
        abortCopy = undefined;
      };
    });
